import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import{matchingRule,movementResult}from'../core.js';import{matchingPhotographs}from'../photographs.js';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url))),rules=read('research-updates-20261008.json').filter(r=>r.baseReference==='168.1640'||r.baseReference==='2780'&&r.brand==='RAYMONDWEIL'),photos=read('photographs.json').photographs.filter(p=>p.id.startsWith('omega-1681640-20261026-'));
test('Internal Omega case code and RaymondWeil bare reference retain limited scope',()=>{assert.equal(rules.length,2);for(const[b,r,c]of [['OMEGA','1681640','1120'],['RAYMONDWEIL','2780','RW 1212'],['RAYMONDWEIL','2780-STC-52001','RW1212']]){const m=matchingRule(rules,b,r);assert.ok(m.manualReview);assert.equal(movementResult(m,c).level,'match');}for(const[b,r]of [['OMEGA','22545000'],['OMEGA','1681644'],['RAYMONDWEIL','2780-SP5-20001']])assert.equal(matchingRule(rules,b,r),null);});
test('Five Omega files explicitly represent one execution and do not inherit retail identity',()=>{assert.equal(photos.length,5);assert.equal(new Set(photos.map(p=>p.image)).size,5);assert.equal(new Set(photos.map(p=>p.category)).size,4);assert.ok(matchingPhotographs(photos,'OMEGA','1681640').every(p=>p.matchScope==='representative variant'));assert.equal(matchingPhotographs(photos,'OMEGA','1681640',{externalOnly:true}).length,4);for(const r of ['22545000','22558000','1681644'])assert.equal(matchingPhotographs(photos,'OMEGA',r).length,0);});
test('Incomplete Oris case fragment remains evidence-needed without supplier equivalence',()=>{const s=read('research-queue-omega-rw-oris-20261026-sources.json').records.find(r=>r.brand==='ORIS');assert.equal(s.decision,'needs_evidence');assert.match(s.conclusion,/not equated/);assert.equal(rules.find(r=>r.brand==='ORIS'),undefined);});
